    for (const k of [0, 0.15, -0.15, 0.3, -0.3, 0.45]) { const c = k >= 0 ? misturaCor(base, "#ffffff", k) : misturaCor(base, "#000000", -k); try { o.cor(c); ok = true; break; } catch (e) { } }
