/* GeoMannequin — Cores e temas (claro, escuro e automático): todas as cores vêm destes tokens */
:root{
  --bg:#E6EBF1;
  --panel:#F4F7FA;
  --paper:#F9FBFD;
  --ink:#15212F;
  --muted:#586577;
  --rule:#C8D1DC;
  --grid:#E3E9F0;
  --grid-major:#CBD4DF;
  --cobalt:#2B63D9;
  --coral:#CF4A27;
  --m-ink:#3E434D;--g-blue:#8DB0E2;--g-red:#E29A9F;--shade3:#A9ABBB;
  --field:#EAEFF4;
  --fill:#F6F4EA;
  --shade1:#E4E4EB;
  --shade2:#CBCCD9;
  --font-display:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;
  --font-body:"Schibsted Grotesk","Segoe UI",system-ui,sans-serif;
  --font-mono:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace;
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#0E141B;--panel:#151D27;--paper:#0F1620;--ink:#E5ECF4;--muted:#93A1B3;--rule:#2A3644;
    --grid:#161F2A;--grid-major:#223040;--cobalt:#6C9CFF;--coral:#FF8564;--field:#1C2632;
    --fill:#3A4556;--shade1:#2E3846;--shade2:#222B38;--shade3:#161D27;--m-ink:#DCE2EC;--g-blue:#6F98D6;--g-red:#D98086;
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#0E141B;--panel:#151D27;--paper:#0F1620;--ink:#E5ECF4;--muted:#93A1B3;--rule:#2A3644;
  --grid:#161F2A;--grid-major:#223040;--cobalt:#6C9CFF;--coral:#FF8564;--field:#1C2632;
  --fill:#3A4556;--shade1:#2E3846;--shade2:#222B38;--shade3:#161D27;--m-ink:#DCE2EC;--g-blue:#6F98D6;--g-red:#D98086;
  color-scheme:dark;
}
